"""Recover atomically committed worker outputs after a process restart."""

import re
import stat

from app_log import get_logger

log = get_logger("runtime")


def completed_output(directory, job_id, extension):
    """Return the committed output path for a job, or None when it is absent or unusable.

    Only a regular, non-empty file counts. Symlinks and other reparse-like entries return None.
    """
    # Only IDs generated by the workers may select a file. Never follow links.
    if not isinstance(job_id, str) or not re.fullmatch(r"[a-f0-9]{32}", job_id):
        return None
    path = directory / f"{job_id}.{extension}"
    try:
        info = path.lstat()
        if not stat.S_ISREG(info.st_mode) or info.st_size == 0:
            return None
    except OSError as error:
        # A missing file is the normal case after a crash, so this is debug, not a warning.
        log.debug("runtime.output.inspect.failed", {"errorClass": type(error).__name__})
        return None
    return path


def recovered_job(directory, job_id, extension, message):
    """Return a completed job record for a committed output, or None if none can be recovered."""
    if completed_output(directory, job_id, extension) is None:
        return None
    return {"id": job_id, "status": "completed", "message": message, "recovered": True}
